log=''
class Proxy:
 @property
 def __bases__(self):
  global log
  log+='b'
  return (int,)
p=Proxy()
result=issubclass(p,int)

log=''
class Proxy:
 def __getattribute__(self,name):
  global log
  if name=='__bases__':
   log+='g'
   return (str,)
  return object.__getattribute__(self,name)
p=Proxy()
p.__bases__=(int,)
result=issubclass(p,int)

class Proxy:
 @property
 def __bases__(self):
  raise ValueError
p=Proxy()
try:
 result=issubclass(p,int)
except ValueError:
 result='caught-value'

